<?php declare(strict_types=1);$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');ob_start(); ?><header class="gateway-page-header"><div><h1 class="gateway-page-header__title">Company Notices</h1><p class="gateway-page-header__description">Create and review official company communications.</p></div><a class="btn btn-primary" href="/company-notices/create">Create Notice</a></header><?php if($success): ?><div class="alert alert-success"><?= $e($success) ?></div><?php endif; ?><div class="gateway-tool-grid mb-4"><a class="gateway-tool-card gateway-tool-card--enabled" href="/company-notices/create"><div class="gateway-tool-card__body"><h2 class="gateway-tool-card__title">Create Notice</h2><p>Compose and publish a company-wide notice.</p></div></a><section class="gateway-tool-card"><div class="gateway-tool-card__body"><h2 class="gateway-tool-card__title">Published Notices</h2><p>Review published communications and acknowledgment status.</p></div></section><section class="gateway-tool-card gateway-tool-card--disabled"><div class="gateway-tool-card__body"><h2 class="gateway-tool-card__title">Drafts</h2><p>Module planned</p></div></section></div><div class="gateway-card"><div class="gateway-card__body"><table class="table"><thead><tr><th>Title</th><th>Priority</th><th>Published By</th><th>Recipients</th><th>Acknowledged</th><th>Outstanding</th><th>Email Status</th><th>Action</th></tr></thead><tbody><?php foreach($published as $n): ?><tr><td><?= $e($n['title']) ?></td><td><?= $e(ucfirst($n['priority'])) ?></td><td><?= $e($n['published_by']) ?></td><td><?= (int)$n['recipients'] ?></td><td><?= (int)$n['acknowledged'] ?></td><td><?= (int)$n['outstanding'] ?></td><td><?= (int)$n['failed']?'Partial':'Delivered' ?></td><td><a href="/company-notices/<?= $e($n['public_id']) ?>">View</a></td></tr><?php endforeach; ?></tbody></table></div></div><?php $contentHtml=(string)ob_get_clean();$pageTitle='Company Notices — NPM Gateway';$navbarItems=\NpmGateway\Support\Navigation::forRoute('/company-notices',dirname(__DIR__,3));$navbarUserLabel=$user->displayName;require dirname(__DIR__).'/layouts/app.php';
